-- Phase 10D: the privilege model that the migrations declare, enforced on hosted Supabase.
--
-- Hosted Supabase grants anon, authenticated and service_role full table and execute rights on objects created by the postgres role.
-- Earlier migrations revoked only some of them, so hosted projects held rights the local tests never exercised. This migration
-- removes every client and worker right from the public schema, then grants back exactly what the application needs.

-- 1. Future objects created by postgres get no client rights. Later migrations grant explicitly.
alter default privileges for role postgres in schema public revoke all on tables from anon, authenticated, service_role;
alter default privileges for role postgres in schema public revoke all on sequences from anon, authenticated, service_role;
alter default privileges for role postgres in schema public revoke all on functions from anon, authenticated, service_role;

-- 2. Remove all client and worker rights from existing public objects.
revoke all on all tables in schema public from anon, authenticated, service_role;
revoke all on all sequences in schema public from anon, authenticated, service_role;
revoke all on all functions in schema public from public, anon, authenticated, service_role;

